import tsugumi

def main(inputs, report):
    result_ports = {}
    value = inputs.params.value
    _number_value = {}
    _number_value['value'] = value
    result_ports.update({'out': _number_value})
    report.scalar(value, 'Python')
    return result_ports

namespace sample;
table Number { value:long; }
table Outputs { out:Number (required); }
root_type Outputs;

{ pkgs, inputs, params }:
let sdk = inputs.tsugumi.sdk { languages = [ "python" ]; };
in { run = inputs.tsugumi.pythonCard { inherit sdk; src = ./src; }; }

def on_run_start(inputs)
  @runs = (@runs || 0) + 1
  nil
end

def main(inputs, report)
  outputs = {}
  received = inputs.input('number').fetch('value')
  result = received * inputs.params.fetch('factor')
  outputs['out'] = {value: result}
  report.log("Ruby run #{@runs}: #{received} -> #{result}")
  report.table(['input', 'factor', 'result'], [[received, inputs.params['factor'], result]])

  outputs
end

